typedef struct {
    const char *title;
    const gfx_image_t *image;
} ui_asset_title_entry_t;

static const ui_asset_title_entry_t s_titles[] = {
    { "PiPod", &s_img_title_pipod },
    { "Music", &s_img_title_music },
    { "Settings", &s_img_title_settings },
    { "Now Playing", &s_img_title_now_playing },
    { "About", &s_img_title_about },
    { "Playlists", &s_img_title_playlists },
    { "Artists", &s_img_title_artists },
    { "Albums", &s_img_title_albums },
    { "Songs", &s_img_title_songs },
};

typedef struct {
    const char *title;
    bool chevron;
    const gfx_image_t *normal;
    const gfx_image_t *selected;
} ui_asset_row_entry_t;

static const ui_asset_row_entry_t s_rows[] = {
    { "Music", true, &s_img_row_music_normal, &s_img_row_music_selected },
    { "Now Playing", true, &s_img_row_now_playing_normal, &s_img_row_now_playing_selected },
    { "Shuffle Songs", false, &s_img_row_shuffle_songs_normal, &s_img_row_shuffle_songs_selected },
    { "Settings", true, &s_img_row_settings_normal, &s_img_row_settings_selected },
    { "Playlists", true, &s_img_row_playlists_normal, &s_img_row_playlists_selected },
    { "Artists", true, &s_img_row_artists_normal, &s_img_row_artists_selected },
    { "Albums", true, &s_img_row_albums_normal, &s_img_row_albums_selected },
    { "Songs", true, &s_img_row_songs_normal, &s_img_row_songs_selected },
    { "About", true, &s_img_row_about_normal, &s_img_row_about_selected },
};

const gfx_image_t *ui_asset_status_title(const char *title) {
    if (title == NULL) {
        return NULL;
    }
    for (size_t i = 0; i < sizeof s_titles / sizeof s_titles[0]; i++) {
        if (strcmp(s_titles[i].title, title) == 0) {
            return s_titles[i].image;
        }
    }
    return NULL;
}

const gfx_image_t *ui_asset_menu_row(const char *title, bool chevron, bool selected) {
    if (title == NULL) {
        return NULL;
    }
    for (size_t i = 0; i < sizeof s_rows / sizeof s_rows[0]; i++) {
        if (s_rows[i].chevron == chevron && strcmp(s_rows[i].title, title) == 0) {
            return selected ? s_rows[i].selected : s_rows[i].normal;
        }
    }
    return NULL;
}
